mapper.update:
UPDATE byai.tenant_config
SET params_value = #{value}, params_version = params_version + 1, updated_at = CURRENT_TIMESTAMP
WHERE enterprise_id = #{enterpriseId} AND params_code = #{code}

mapper.delete:
DELETE FROM byai.tenant_config
WHERE enterprise_id = #{enterpriseId}
  AND params_code NOT IN ('PROVISION_REQUEST_ID', 'PROVISION_STATE', 'TENANT_DELETE_REQUESTED')
